do $$ declare i record;n integer;paid numeric;ref text;begin for i in select inv.*,s.admission_number from schoolpro_invoices inv join schoolpro_students s on s.id=inv.student_id where inv.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and inv.session='2025/2026' and s.admission_number like 'IH-TST-2026-%' loop n:=right(i.admission_number,3)::integer;paid:=case when n%4=0 then 0 when n%4=3 then round(i.amount_due/2,2) else i.amount_due end;ref:='TEST-SIMULATED-'||i.id::text;if paid>0 and not exists(select 1 from schoolpro_fee_payments where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and reference=ref)then perform record_schoolpro_payment(i.id,greatest(paid-i.amount_paid,0),'other',ref,'SIMULATED school fee receipt for Academy testing; no money received.');end if;end loop;end $$;
insert into schoolpro_finance_settings(school_id,block_results_when_owing,allowed_outstanding,block_results_for_attendance,minimum_attendance_percent,updated_by)values('d342eb87-8d6a-477a-a380-7fab83f586b7',true,1000,true,70,'7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d') on conflict(school_id)do update set block_results_when_owing=true,allowed_outstanding=1000,block_results_for_attendance=true,minimum_attendance_percent=70,updated_by='7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d';
do $$ declare s record;t text;begin for s in select id from schoolpro_students where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and admission_number like 'IH-TST-2026-%' and right(admission_number,3)::int=4 loop foreach t in array array['First Term','Second Term','Third Term'] loop perform schoolpro_set_result_access_exception(s.id,t,'2025/2026',true,'TEST: School leadership permits this unpaid pupil to view the published result.');end loop;end loop;end $$;
update schoolpro_attendance a set status='absent',notes='TEST: low attendance scenario' from schoolpro_students s where s.id=a.student_id and a.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and right(s.admission_number,3)::int=5 and extract(isodow from a.attendance_date) in(1,2,3) and a.attendance_date between '2025-09-15' and '2026-07-10';

